const client = $("Extract Payment Details").first().json;
const cfg = $("Prepare Channel & Team Config").first().json;
const channel = $("Create Client Slack Channel").first().json;
let agent = {};
try {
  agent = $("Supervisor: Onboarding Agent").first().json || {};
} catch (e) {
  agent = {};
}
const clean = (s) => String(s || "").replace(/[\r\n]+/g, " ").trim();
const esc = (s) => clean(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
const name = clean(client.clientName).slice(0, 100) || "there";
const isSlackId = (id) => /^[UW][A-Z0-9]{6,}$/.test(id || "");
const am = isSlackId(cfg.accountManagerSlackId) ? "<@" + cfg.accountManagerSlackId + ">" : "your Account Manager";
const ol = isSlackId(cfg.onboardingLeadSlackId) ? "<@" + cfg.onboardingLeadSlackId + ">" : "the Onboarding Lead";
const tier = esc(client.serviceTier).slice(0, 80) || "Service";
const paid = esc(client.amountPaid + " " + client.currency);
const summary = typeof agent.welcomeSummary === "string" && agent.welcomeSummary.trim() ? esc(agent.welcomeSummary).slice(0, 500) : "";
const agentSteps = Array.isArray(agent.onboardingSteps)
  ? agent.onboardingSteps.filter((s) => typeof s === "string" && s.trim()).slice(0, 6).map((s) => esc(s).slice(0, 250))
  : [];
const steps = agentSteps.length >= 3
  ? agentSteps
  : [
      "Kick-off: " + am + " will propose a kick-off call time here.",
      "Access: share any accounts, assets or documents we need in this channel.",
      "Scope: " + ol + " will confirm the scope, milestones and timeline.",
      "Updates: project status and questions are handled in this channel."
    ];
const stepsText = "*Project onboarding steps*\n" + steps.map((s, i) => (i + 1) + ". " + s).join("\n");
const blocks = [
  { type: "header", text: { type: "plain_text", text: "Welcome aboard, " + name + "!", emoji: true } },
  { type: "section", text: { type: "mrkdwn", text: "Thank you for your payment of *" + paid + "* for the *" + tier + "* package. Your engagement is now *active* and this private channel is your dedicated workspace with our team." } }
];
if (summary) {
  blocks.push({ type: "section", text: { type: "mrkdwn", text: summary } });
}
blocks.push({ type: "divider" });
blocks.push({ type: "section", fields: [
  { type: "mrkdwn", text: "*Account Manager*\n" + am },
  { type: "mrkdwn", text: "*Onboarding Lead*\n" + ol },
  { type: "mrkdwn", text: "*Service Tier*\n" + tier },
  { type: "mrkdwn", text: "*Payment Reference*\n" + esc(client.sessionId) }
] });
blocks.push({ type: "section", text: { type: "mrkdwn", text: stepsText } });
blocks.push({ type: "context", elements: [ { type: "mrkdwn", text: "Reply here any time and the team will pick it up." } ] });
return [{ json: { channelId: channel.id, text: "Welcome aboard, " + name + "! Your engagement is now active.", blocksJson: JSON.stringify({ blocks: blocks }) } }];

