const rows = $input.all().map((i) => i.json).filter((r) => r && (r.id || r.fields));
const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

// دالة لاستخراج قيمة أي حقل سواء كان داخل fields أو في الـ root مباشرة
const getVal = (r, fieldName) => {
  if (r.fields && r.fields[fieldName] !== undefined) {
    return r.fields[fieldName];
  }
  return r[fieldName];
};

// تحويل المبلغ لرقم
const amt = (r) => {
  const val = getVal(r, "Amount");
  return typeof val === 'number' ? val : parseFloat(val) || 0;
};

const sum = (arr) => Math.round(arr.reduce((t, r) => t + amt(r), 0) * 100) / 100;

// فحص حالة العميل
const isActive = (r) => {
  const status = (getVal(r, "Status") || "").toString().trim().toLowerCase();
  return status.includes("paid") || status.includes("active");
};

const isPending = (r) => {
  const status = (getVal(r, "Status") || "").toString().trim().toLowerCase();
  return status.includes("pending");
};

// فحص تاريخ التسجيل (باستخدام createdTime الخاص بـ Airtable)
const isNew = (r) => {
  const created = r.createdTime || getVal(r, "createdTime");
  return created && new Date(created) >= weekAgo;
};

const active = rows.filter(isActive);
const pending = rows.filter(isPending);
const fresh = rows.filter(isNew);

const tiers = {};
active.forEach((r) => { 
  const t = getVal(r, "Service Tier") || "Unspecified"; 
  tiers[t] = (tiers[t] || 0) + 1; 
});

const clientNames = fresh.map((r) => getVal(r, "Client Name")).filter(Boolean);

return [{ json: {
  weekEnding: now.toISOString().slice(0, 10),
  totalClients: rows.length,
  activeClients: active.length,
  totalRevenue: sum(active),
  pendingPaymentsCount: pending.length,
  pendingPaymentsValue: sum(pending),
  newSignupsThisWeek: fresh.length,
  newSignupsPaid: fresh.filter(isActive).length,
  newSignupsRevenue: sum(fresh.filter(isActive)),
  activeClientsByTier: tiers,
  newClientNames: clientNames
} }];

