const contractText = String($input.first().json.text || "").replace(/\r\n/g, "\n").trim();
if (!contractText) {
  throw new Error("Contract Agent returned no contract text, cannot build the PDF");
}
const client = $("Normalize Intake Payload").first().json;
const esc = (s) => String(s === undefined || s === null ? "" : s)
  .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");

const lines = contractText.split("\n").map((l) => l.replace(/\s+$/g, ""));
const blocks = [];
let para = [];
let list = [];
let started = false;
const flushPara = () => {
  if (para.length) { blocks.push('<p dir="auto">' + para.map(esc).join("<br>") + "</p>"); para = []; }
};
const flushList = () => {
  if (list.length) { blocks.push('<ul dir="auto">' + list.map((li) => "<li>" + esc(li) + "</li>").join("") + "</ul>"); list = []; }
};
for (const raw of lines) {
  const line = raw.trim();
  if (!line) { flushPara(); flushList(); continue; }
  if (/^_{5,}$/.test(line)) { flushPara(); flushList(); blocks.push('<div class="sig-line"></div>'); started = true; continue; }
  const bullet = line.match(/^[-\u2022*]\s+(.*)$/);
  if (bullet) { flushPara(); list.push(bullet[1]); started = true; continue; }
  flushList();
  const isNumbered = /^\d+[.)]\s+[^.!?:;]{1,70}$/.test(line);
  const isCaps = /^[A-Z0-9][A-Z0-9 &\/,'()\-]{2,70}$/.test(line) && /[A-Z]/.test(line);
  if (!started && isCaps) { blocks.push('<h1 dir="auto">' + esc(line) + "</h1>"); started = true; continue; }
  started = true;
  if (isNumbered || isCaps) { flushPara(); blocks.push('<h2 dir="auto">' + esc(line) + "</h2>"); continue; }
  para.push(line);
}
flushPara();
flushList();

const currency = String(client.currency || "").toUpperCase();
const feeText = client.amount ? client.amount + " " + currency : "";
const meta = '<table class="meta">'
  + '<tr><th>Client</th><td dir="auto">' + esc(client.clientName) + "</td></tr>"
  + '<tr><th>Email</th><td dir="auto">' + esc(client.clientEmail) + "</td></tr>"
  + '<tr><th>Service package</th><td dir="auto">' + esc(client.serviceTier) + "</td></tr>"
  + '<tr><th>Fee</th><td dir="auto">' + esc(feeText) + "</td></tr>"
  + "</table>";
if (blocks.length && blocks[0].indexOf("<h1") === 0) {
  blocks.splice(1, 0, meta);
} else {
  blocks.unshift('<h1>Service Agreement</h1>', meta);
}

const css = [
  "@page { size: A4; margin: 22mm 20mm; }",
  "* { box-sizing: border-box; }",
  'body { font-family: Georgia, "Times New Roman", "Noto Serif", serif; font-size: 11pt; line-height: 1.55; color: #1f2937; margin: 0; }',
  "h1 { font-size: 20pt; letter-spacing: 0.08em; text-transform: uppercase; text-align: center; margin: 0 0 14px; padding-bottom: 10px; border-bottom: 2px solid #1f2937; }",
  "h2 { font-size: 12pt; margin: 20px 0 6px; padding-bottom: 3px; border-bottom: 1px solid #d1d5db; break-after: avoid; }",
  "p { margin: 0 0 9px; orphans: 3; widows: 3; }",
  "ul { margin: 0 0 9px; padding-left: 22px; }",
  "li { margin-bottom: 3px; }",
  ".meta { width: 100%; border-collapse: collapse; margin: 0 0 8px; font-size: 10.5pt; }",
  ".meta th, .meta td { border: 1px solid #d1d5db; padding: 6px 10px; text-align: left; vertical-align: top; }",
  ".meta th { width: 30%; background: #f3f4f6; font-weight: bold; }",
  ".sig-line { border-bottom: 1px solid #1f2937; height: 30px; width: 60%; margin: 16px 0 2px; }"
].join("\n");

const html = '<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<title>Service Agreement - ' + esc(client.clientName) + "</title>\n<style>\n" + css + "\n</style>\n</head>\n<body>\n" + blocks.join("\n") + "\n</body>\n</html>";

const safeName = String(client.clientName || "").replace(/[\\\/:*?"<>|\u0000-\u001f]+/g, " ").replace(/\s+/g, " ").trim().slice(0, 60) || "Client";
const pdfFileName = "Service Agreement - " + safeName + " - " + new Date().toISOString().slice(0, 10) + ".pdf";

return [{ json: { html: html, pdfFileName: pdfFileName } }];

const meta = $("Build Contract HTML").first().json;
const item = $input.first();
if (!item.binary || !item.binary.contractPdf) {
  throw new Error("Gotenberg did not return a PDF (binary property contractPdf is missing)");
}
const buf = await this.helpers.getBinaryDataBuffer(0, "contractPdf");
if (buf.length < 100 || buf.subarray(0, 5).toString("latin1") !== "%PDF-") {
  throw new Error("Gotenberg response is not a valid PDF");
}
item.binary.contractPdf.fileName = meta.pdfFileName;
item.binary.contractPdf.mimeType = "application/pdf";
return [{ json: { pdfFileName: meta.pdfFileName, pdfBytes: buf.length }, binary: item.binary }];

